def f(N, A, M, O):
    """
    N: an integer
    A: a list of tuples, where each tuple contains a strings and integers
    M: an integer
    O: a list of strings

    Purpose
    This function will take in input and return
    the result of the badge operation.

    OUTPUT
    The resulting value 
    """
    again = True
    result = []

    while again:
        pairs1 = {}
        pairs2 = {}
        for a, b in A:
            if a in pairs1:
                pairs1[a] += b
            else:
                pairs1[a] = b

            if a in pairs2:
                pairs2[a] -= b
            else:
                pairs2[a] = -b

        for o in O:
            if (o in pairs1 and pairs1[o]>0) or (o in pairs2 and pairs2[o]<0):
                i = pairs1[o] if o in pairs1 else pairs2[o]
                result.append(i)
                pairs1[o] -= 1
                pairs2[o] += 1
            else:
                break
            if len(result) == M:
                again = False
        if len(result)!= M:
            again = False

    return result
